  "helpGuides.content.first-generation.s1.title": "Studioを開く",
  "helpGuides.content.first-generation.s2.body": "右側の一覧に、すべてのモデルがクレジット価格付きで表示されます。画像、動画、音声のモデルはすべて同じ残高から消費されます。",
